  while (list.length >= maxVoices) {
    const old = list.shift();
    try { old.stop(); } catch (_) { /* already stopped */ }
    _removeGlobal(old);
  }

  // Priority sound playing — clear quiet distant voices from the mix
  if (priority > 0) _evictLowPriorityVoices();

